detaileddescription.para:
Usage example: sf::Anglea1=sf::degrees(90);
floatradians=a1.asRadians();//1.5708f

sf::Anglea2=sf::radians(3.141592654f);
floatdegrees=a2.asDegrees();//180.0f

usingnamespacesf::Literals;
sf::Anglea3=10_deg;//10degrees
sf::Anglea4=1.5_deg;//1.5degrees
sf::Anglea5=1_rad;//1radians
sf::Anglea6=3.14_rad;//3.14radians
